{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 유료 공원 단체 입장료 할인 대상 여부(30명)",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 별표 1 비고는 ‘단 체’를 ‘30명 이상 같은 목적으로 동시에 입장하는 경우’로 정하고 있으므로, 딱 30명이어도 인원 수 요건은 충족한다. 다만 조례 제20조제2항제3호는 30명 이상의 단체에 대해 100분의 30 이상 100분의 50 이하의 범위에서 규칙이 정하는 바에 따라 입장료를 감면할 수 있다고 규정하므로, 실제 감면 여부와 감면율은 규칙이 정하는 바에 따른다.",
          "b_ids": "도시공원:별표1#비고1, 도시공원:제20조제2항제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
